css:
.payment-voucher {
  width: 190mm;
  margin: 0 auto;
  font-family: "Helvetica", "Arial", sans-serif;
  font-size: 11px;
}

/* Header */
.voucher-header {
  text-align: center;
  margin-bottom: 8px;
}
.voucher-header h3 {
  margin: 0;
  font-size: 16px;
  text-transform: uppercase;
}
.voucher-header p {
  margin: 0;
  font-size: 11px;
}
.voucher-header h4 {
  margin: 6px 0 0 0;
  font-size: 13px;
  text-decoration: underline;
}

/* Meta table (No., Date, Through) */
.voucher-meta {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 6px;
}
.voucher-meta td {
  padding: 2px 0;
}

/* Main table */
.main-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 4px;
}
.main-table th,
.main-table td {
  border: 1px solid #000;
  padding: 4px 6px;
}
.main-table th {
  font-weight: bold;
  text-align: center;
}
.particulars-head {
  width: auto;
}
.amount-head {
  width: 120px;
}
.main-table td {
  vertical-align: top;
}

/* Left side cell */
.particulars-cell {
  padding: 6px;
}
.party-name {
  font-weight: bold;
  margin: 2px 0 4px 0;
}

/* References (Agst Ref table) */
.ref-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
}
.ref-table td {
  border: none;
  padding: 0 2px;
  line-height: 1.4;
}
.ref-prefix {
  width: 55px;
}
.ref-no {
  /* invoice number area */
}
.ref-amt {
  width: 80px;
}
.ref-drcr {
  width: 25px;
  text-align: right;
}

/* Right side total amount */
.amount-cell {
  width: 120px;
  text-align: right;
  vertical-align: top;
}
.total-amount-box {
  margin-top: 10px;
  padding: 4px 6px;
  border: 1px solid #000;
  font-weight: bold;
}

/* Bottom section */
.footer-section {
  margin-top: 10px;
  font-size: 11px;
}
.footer-section p {
  margin: 2px 0;
}
.amount-words {
  margin-top: 2px;
}

/* Signatures */
.signature-table {
  width: 100%;
  margin-top: 26px;
}
.signature-table td {
  padding-top: 20px;
  font-size: 11px;
}

/* Utilities */
.text-right {
  text-align: right;
}
